import{_ as e,c as r,o as h,af as i}from"./chunks/framework.BKeRpnBD.js";const p=JSON.parse('{"title":"兌","description":"周易正义 - 兌","frontmatter":{"title":"兌","description":"周易正义 - 兌"},"headers":[],"relativePath":"zh/classics/zhengyi/058.md","filePath":"zh/classics/zhengyi/058.md"}'),l={name:"zh/classics/zhengyi/058.md"};function n(d,a,t,o,s,c){return h(),r("div",null,[...a[0]||(a[0]=[i('<blockquote><p>兑为泽</p></blockquote><blockquote><p>卦辞：亨，利贞。</p></blockquote><blockquote><p>彖曰：兑，说也。刚中而柔外，说以利贞，是以顺乎天而应乎人。说以先民，民忘其劳。说以犯难，民忘其死。说之大，民劝矣哉！</p></blockquote><h1 id="兌" tabindex="-1">兌 <a class="header-anchor" href="#兌" aria-label="Permalink to “兌”">​</a></h1><h3 id="疏" tabindex="-1">疏 <a class="header-anchor" href="#疏" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：兑，说也。《说卦》曰：“说万物者莫说乎泽。”以兑是象泽之卦，故以“兑”为名。泽以润生万物，所以万物皆说：施於人事，犹人君以恩惠养民，民无不说也。惠施民说，所以为亨。以说说物，恐陷谄邪，其利在於贞正。故曰“兑，亨利贞”。</p><h2 id="《彖》曰-​" tabindex="-1">《彖》曰： ​ <a class="header-anchor" href="#《彖》曰-​" aria-label="Permalink to “《彖》曰： ​”">​</a></h2><h3 id="兑-说也。刚中而柔外-说以利贞-​" tabindex="-1">兑，说也。刚中而柔外，说以利贞， ​ <a class="header-anchor" href="#兑-说也。刚中而柔外-说以利贞-​" aria-label="Permalink to “兑，说也。刚中而柔外，说以利贞， ​”">​</a></h3><p>王弼：说而违刚则谄，刚而违说则暴。刚中而柔外，所以说以利贞也。刚中，故利贞，柔外，故说亨。</p><h3 id="疏-1" tabindex="-1">疏 <a class="header-anchor" href="#疏-1" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：“兑，说也”者，训卦名也。“刚中而柔外，说以利贞”者，此就二、五以刚居中，上六、六三以柔处外，释“兑亨利贞”之义也。外虽柔说，而内德刚正，则不畏邪谄。内虽刚正，而外迹柔说，则不忧侵暴。只为刚中而柔外，中外相济，故得说亨而利贞也。</p><h3 id="是以顺乎天而应乎人。-​" tabindex="-1">是以顺乎天而应乎人。 ​ <a class="header-anchor" href="#是以顺乎天而应乎人。-​" aria-label="Permalink to “是以顺乎天而应乎人。 ​”">​</a></h3><p>王弼：天刚而不失说者也。</p><h3 id="疏-2" tabindex="-1">疏 <a class="header-anchor" href="#疏-2" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：广明说义，合於天人。天为刚德而有柔克，是刚而不失其说也。今说以利贞，是上顺乎天也。人心说於惠泽，能以惠泽说人，是下应乎人也。</p><h3 id="说以先民-民忘其劳-说以犯难-民忘其死。说之大-民劝矣哉-​" tabindex="-1">说以先民，民忘其劳；说以犯难，民忘其死。说之大，民劝矣哉！ ​ <a class="header-anchor" href="#说以先民-民忘其劳-说以犯难-民忘其死。说之大-民劝矣哉-​" aria-label="Permalink to “说以先民，民忘其劳；说以犯难，民忘其死。说之大，民劝矣哉！ ​”">​</a></h3><h3 id="疏-3" tabindex="-1">疏 <a class="header-anchor" href="#疏-3" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：“说以先民，民忘其劳”，以下叹美说之所致，亦申明应人之法，先以说豫抚民，然后使之从事，则民皆竭力忘其从事之劳，故曰“说以先民，民忘其劳”也。“说以犯难，民忘其死”者，先以说豫劳民，然后使之犯难，则民皆授命，忘其犯难之死，故曰“说以犯难，民忘其死”也。施说於人，所致如此，岂非说义之大，能使民劝勉矣哉！故曰“说之大，民劝矣哉”。</p><h2 id="《象》曰-丽泽-兑。君子以朋友讲习。-​" tabindex="-1">《象》曰：丽泽，兑。君子以朋友讲习。 ​ <a class="header-anchor" href="#《象》曰-丽泽-兑。君子以朋友讲习。-​" aria-label="Permalink to “《象》曰：丽泽，兑。君子以朋友讲习。 ​”">​</a></h2><p>王弼：丽，犹连也。施说之盛，莫盛於此。</p><h3 id="疏-4" tabindex="-1">疏 <a class="header-anchor" href="#疏-4" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：“丽泽兑”者，丽，犹连也，两泽相连，润说之盛，故曰“丽泽，兑”也。“君子以朋友讲习”者，同门曰朋，同志曰友，朋友聚居，讲习道义，相说之盛，莫过於此也。故君子象之以朋友讲习也。</p><h2 id="初九-和兑-吉。-​" tabindex="-1">初九：和兑，吉。 ​ <a class="header-anchor" href="#初九-和兑-吉。-​" aria-label="Permalink to “初九：和兑，吉。 ​”">​</a></h2><p>王弼：居兑之初，应不在一，无所党系，和兑之谓也。说不在谄，履斯而行，未见有疑之者，吉其宜矣。。</p><h3 id="疏-5" tabindex="-1">疏 <a class="header-anchor" href="#疏-5" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：初九居兑之初，应不在一，无所私说，说之和也，说物以和，何往不吉，故曰“和兑，吉”也。</p><h3 id="《象》曰-和兑-之-吉-行未疑也。-​" tabindex="-1">《象》曰：“和兑”之“吉”，行未疑也。 ​ <a class="header-anchor" href="#《象》曰-和兑-之-吉-行未疑也。-​" aria-label="Permalink to “《象》曰：“和兑”之“吉”，行未疑也。 ​”">​</a></h3><h3 id="疏-6" tabindex="-1">疏 <a class="header-anchor" href="#疏-6" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：“行未疑”者，说不为谄，履斯而行，未见疑之者也，所以得吉也。</p><h2 id="九二-孚兑-吉-悔亡。-​" tabindex="-1">九二：孚兑，吉，悔亡。 ​ <a class="header-anchor" href="#九二-孚兑-吉-悔亡。-​" aria-label="Permalink to “九二：孚兑，吉，悔亡。 ​”">​</a></h2><p>王弼：说不失中，有孚者也。失位而说，孚吉，乃悔亡也。</p><h3 id="疏-7" tabindex="-1">疏 <a class="header-anchor" href="#疏-7" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：九二说不失中，有信者也。说而有信，则吉从之，故曰“孚兑，吉”也。然履失其位，有信而吉，乃得亡悔，故曰“孚兑，吉，悔亡”也。</p><h3 id="《象》曰-孚兑-之-吉-信志也。-​" tabindex="-1">《象》曰：“孚兑”之“吉”，信志也。 ​ <a class="header-anchor" href="#《象》曰-孚兑-之-吉-信志也。-​" aria-label="Permalink to “《象》曰：“孚兑”之“吉”，信志也。 ​”">​</a></h3><p>王弼：其志信也。</p><h3 id="疏-8" tabindex="-1">疏 <a class="header-anchor" href="#疏-8" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：“信志也”者，失位而得吉，是其志信也。</p><h2 id="六三-来兑-凶。-​" tabindex="-1">六三：来兑，凶。 ​ <a class="header-anchor" href="#六三-来兑-凶。-​" aria-label="Permalink to “六三：来兑，凶。 ​”">​</a></h2><p>王弼：以阴柔之质，履非其位，来求说者也。非正而求说，邪佞者也。</p><h3 id="疏-9" tabindex="-1">疏 <a class="header-anchor" href="#疏-9" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：三为阳位，阴来居之，是进来求说，故言“来兑”；而以不正来说，佞邪之道，故曰：“来兑，凶”也。</p><h3 id="《象》曰-来兑-之-凶-位不当也。-​" tabindex="-1">《象》曰：“来兑”之“凶”，位不当也。 ​ <a class="header-anchor" href="#《象》曰-来兑-之-凶-位不当也。-​" aria-label="Permalink to “《象》曰：“来兑”之“凶”，位不当也。 ​”">​</a></h3><h3 id="疏-10" tabindex="-1">疏 <a class="header-anchor" href="#疏-10" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：“位不当”者，由位不当，所以致凶也。</p><h2 id="九四-商兑未宁-介疾有喜。-​" tabindex="-1">九四：商兑未宁，介疾有喜。 ​ <a class="header-anchor" href="#九四-商兑未宁-介疾有喜。-​" aria-label="Permalink to “九四：商兑未宁，介疾有喜。 ​”">​</a></h2><p>王弼：商，商量裁制之谓也。介，隔也。三为佞说，将近至尊。故四以刚德，裁而隔之，匡内制外，是以未宁也。处於几近，闲邪介疾，宜其有喜也。</p><h3 id="疏-11" tabindex="-1">疏 <a class="header-anchor" href="#疏-11" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：“商兑未宁”者，商，商量裁制之谓也。夫佞邪之人，国之疾也。三为佞说，将近至尊。故四以刚德，裁而隔之，使三不得进，匡内制外，未遑宁处，故曰“商兑未宁”。居近至尊，防邪隔疾，宜其有喜，故曰“介疾有喜”。</p><h3 id="《象》曰-九四-之-喜-有庆也。-​" tabindex="-1">《象》曰：“九四”之“喜”，有庆也。 ​ <a class="header-anchor" href="#《象》曰-九四-之-喜-有庆也。-​" aria-label="Permalink to “《象》曰：“九四”之“喜”，有庆也。 ​”">​</a></h3><h3 id="疏-12" tabindex="-1">疏 <a class="header-anchor" href="#疏-12" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：“有庆”者，四能匡内制外，介疾除邪，此之为喜，乃为至尊所善，天下蒙赖，故言“有庆”也。</p><h2 id="九五-孚于剥-有厉。-​" tabindex="-1">九五：孚于剥，有厉。 ​ <a class="header-anchor" href="#九五-孚于剥-有厉。-​" aria-label="Permalink to “九五：孚于剥，有厉。 ​”">​</a></h2><p>王弼：比於上六，而与相得，处尊正之位，不说信乎阳，而说信乎阴，“孚于剥”之义也。“剥”之为义，小人道长之谓。</p><h3 id="疏-13" tabindex="-1">疏 <a class="header-anchor" href="#疏-13" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：“剥”者，小人道长，消君子之正，故谓小人为剥也。九五，处尊正之位，下无其应，比於上六，与之相得，是说信於小人，故曰“孚于剥”。信而成剥，危之道也，故曰“有厉”。</p><h3 id="《象》曰-孚于剥-位正当也。-​" tabindex="-1">《象》曰：“孚于剥”，位正当也。 ​ <a class="header-anchor" href="#《象》曰-孚于剥-位正当也。-​" aria-label="Permalink to “《象》曰：“孚于剥”，位正当也。 ​”">​</a></h3><p>王弼：以正当之位，信於小人而疏君子，故曰“位正当”也。</p><h3 id="疏-14" tabindex="-1">疏 <a class="header-anchor" href="#疏-14" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：“位正当”者，以正当之位，宜在君子，而信小人，故以当位责之也。</p><h2 id="上六-引兑。-​" tabindex="-1">上六：引兑。 ​ <a class="header-anchor" href="#上六-引兑。-​" aria-label="Permalink to “上六：引兑。 ​”">​</a></h2><p>王弼：以夫阴质，最处说后，静退者也。故必见引，然后乃说也。</p><h3 id="疏-15" tabindex="-1">疏 <a class="header-anchor" href="#疏-15" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：上六以阴柔之质，最在兑后，是自静退，不同六三自进求说，必须他人见引，然后乃说，故曰“引兑”也。</p><h3 id="《象》曰-上六-引兑-未光也。-​" tabindex="-1">《象》曰：“上六，引兑”，未光也。 ​ <a class="header-anchor" href="#《象》曰-上六-引兑-未光也。-​" aria-label="Permalink to “《象》曰：“上六，引兑”，未光也。 ​”">​</a></h3><h3 id="疏-16" tabindex="-1">疏 <a class="header-anchor" href="#疏-16" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：“未光也”者，虽免躁求之凶，亦有后时之失，所以《经》无“吉”文，以其道未光故也。</p>',66)])])}const f=e(l,[["render",n]]);export{p as __pageData,f as default};
